import Flutter
import UIKit
import UniformTypeIdentifiers

/// A user-granted folder exposed as `/project` to the Dart mount layer and
/// the WASI preopened-directory list. The URL is retained for the app's
/// lifetime; stopping one bookmark must not revoke a live WASI command.
private final class FaProjectFolderPicker: NSObject, UIDocumentPickerDelegate {
  var completion: ((URL?) -> Void)?
  var grantedURL: URL?

  func pick(from controller: UIViewController?, completion: @escaping (URL?) -> Void) {
    self.completion = completion
    let picker = UIDocumentPickerViewController(forOpeningContentTypes: [.folder])
    picker.delegate = self
    picker.allowsMultipleSelection = false
    picker.shouldShowFileExtensions = true
    guard let controller else {
      self.completion = nil
      completion(nil)
      return
    }
    #if DEBUG
    print("[fah] project folder picker: presenting from \(type(of: controller))")
    #endif
    controller.present(picker, animated: true) {
      #if DEBUG
      print("[fah] project folder picker: presented")
      #endif
    }
  }

  func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) {
    guard let url = urls.first else {
      completion?(nil)
      completion = nil
      return
    }
    grantedURL?.stopAccessingSecurityScopedResource()
    grantedURL = url
    _ = url.startAccessingSecurityScopedResource()
    completion?(url)
    completion = nil
  }

  func documentPickerWasCancelled(_ controller: UIDocumentPickerViewController) {
    completion?(nil)
    completion = nil
  }
}

private let faProjectFolderPicker = FaProjectFolderPicker()
private var faProjectFolderBookmarks: [String: URL] = [:]

/// The visible controller in the foreground scene. Presenting on the root
/// controller is unreliable with scene-based Flutter and native presented
/// flows: UIKit can reject the picker without invoking any Dart callback.
private func faVisibleViewController() -> UIViewController? {
  let scenes = UIApplication.shared.connectedScenes
    .compactMap { $0 as? UIWindowScene }
  let foreground = scenes.filter { $0.activationState == .foregroundActive }
  let candidates = foreground.isEmpty ? scenes : foreground
  let windows = candidates.flatMap { $0.windows }
  let window = windows.first { $0.isKeyWindow } ?? windows.first {
    !$0.isHidden && $0.alpha > 0
  }
  func top(_ base: UIViewController?) -> UIViewController? {
    guard let base else { return nil }
    if let presented = base.presentedViewController {
      return top(presented)
    }
    if let navigation = base as? UINavigationController {
      return top(navigation.visibleViewController)
    }
    if let tabs = base as? UITabBarController {
      return top(tabs.selectedViewController)
    }
    return base
  }
  return top(window?.rootViewController)
}

/// The iOS implementation of the shared `fah/project_folder` channel used by
/// the existing macOS mount flow. Bookmarks never contain file contents.
func registerProjectFolderChannel(messenger: FlutterBinaryMessenger) {
  let channel = FlutterMethodChannel(name: "fah/project_folder", binaryMessenger: messenger)
  channel.setMethodCallHandler { call, result in
    switch call.method {
    case "pickDirectory":
      faProjectFolderPicker.pick(from: faVisibleViewController()) { url in
        guard let url else {
          result(nil)
          return
        }
        do {
          let bookmark = try url.bookmarkData(
            options: [],
            includingResourceValuesForKeys: nil,
            relativeTo: nil
          )
          faProjectFolderBookmarks[bookmark.base64EncodedString()] = url
          result(["path": url.path, "bookmark": bookmark.base64EncodedString()])
        } catch {
          result(FlutterError(code: "bookmark_failed", message: error.localizedDescription, details: nil))
        }
      }
    case "startAccessing":
      guard let encoded = call.arguments as? String,
            let bookmark = Data(base64Encoded: encoded) else {
        result(false)
        return
      }
      do {
        var stale = false
        let url = try URL(
          resolvingBookmarkData: bookmark,
          options: [],
          relativeTo: nil,
          bookmarkDataIsStale: &stale
        )
        let granted = url.startAccessingSecurityScopedResource()
        if granted {
          faProjectFolderBookmarks[encoded] = url
          faProjectFolderPicker.grantedURL = url
        }
        result(granted)
      } catch {
        result(false)
      }
    case "stopAccessing":
      guard let encoded = call.arguments as? String else {
        result(nil)
        return
      }
      faProjectFolderBookmarks.removeValue(forKey: encoded)?.stopAccessingSecurityScopedResource()
      result(nil)
    default:
      result(FlutterMethodNotImplemented)
    }
  }
}

import Flutter
import UIKit

/// UIKit's adaptive-layout signals for the Flutter shell. Device identity is
/// diagnostic; `verticalBarEdge` and reserved regions own layout decisions.
@MainActor
private final class FaDuoLayoutChannel: NSObject {
  private weak var observedController: FlutterViewController?
  private let channel: FlutterMethodChannel

  private var controller: FlutterViewController? {
    UIApplication.shared.connectedScenes
      .compactMap { $0 as? UIWindowScene }
      .flatMap { $0.windows }
      .first { $0.isKeyWindow }?.rootViewController as? FlutterViewController
  }

  init(messenger: FlutterBinaryMessenger) {
    channel = FlutterMethodChannel(name: "fah/duo_layout", binaryMessenger: messenger)
    super.init()
    channel.setMethodCallHandler { [weak self] call, result in
      guard let self else { return }
      switch call.method {
      case "snapshot":
        result(self.snapshot())
      default:
        result(FlutterMethodNotImplemented)
      }
    }
    let center = NotificationCenter.default
    center.addObserver(self, selector: #selector(notifySoon), name: UIDevice.orientationDidChangeNotification, object: nil)
    center.addObserver(self, selector: #selector(notifySoon), name: UIApplication.didBecomeActiveNotification, object: nil)
    notifySoon()
  }

  private func installTraitObserverIfNeeded() {
    guard #available(iOS 27.1, *), observedController == nil,
          let controller else { return }
    observedController = controller
    controller.registerForTraitChanges(UITraitCollection.systemTraitsAffectingVerticalBarEdge) {
      [weak self] (_: FlutterViewController, _: UITraitCollection) in
      self?.notifySoon()
    }
  }

  @objc private func notifySoon() {
    // Trait callbacks can precede the view's next layout pass.
    DispatchQueue.main.async { [weak self] in
      self?.installTraitObserverIfNeeded()
      self?.channel.invokeMethod("layoutChanged", arguments: nil)
    }
  }

  private func hardwareModel() -> String {
    if let simulator = ProcessInfo.processInfo.environment["SIMULATOR_MODEL_IDENTIFIER"] {
      return simulator
    }
    var size = 0
    sysctlbyname("hw.machine", nil, &size, nil, 0)
    guard size > 0 else { return "" }
    var machine = [CChar](repeating: 0, count: size)
    sysctlbyname("hw.machine", &machine, &size, nil, 0)
    return String(cString: machine)
  }

  private func snapshot() -> [String: Any] {
    installTraitObserverIfNeeded()
    guard #available(iOS 27.1, *), let view = controller?.view else {
      return [
        "isDuo": false,
        "hardwareModel": hardwareModel(),
        "verticalBarEdge": 0,
        "safeArea": ["left": 0, "top": 0, "right": 0, "bottom": 0],
        "occlusions": [],
        "divisions": [],
      ]
    }
    let model = hardwareModel()
    let edge = controller?.traitCollection.verticalBarEdge ?? .unspecified
    let occlusions = view.reservedRegions(kind: .occlusion, options: [.includeInactive])
    let divisions = view.reservedRegions(kind: .division, options: [.includeInactive])
    // iPhone19,4 is the Xcode 27 Duo simulator/hardware identifier. The
    // vertical-bar trait also recognizes future identifiers; an active fold
    // keeps partially folded poses covered when no vertical bar is preferred.
    let isDuo = model == "iPhone19,4" || model.lowercased().contains("duo") ||
      edge != .unspecified || divisions.contains { $0.isActive }
    let safe = view.safeAreaInsets
    let payload: [String: Any] = [
      "isDuo": isDuo,
      "hardwareModel": model,
      "verticalBarEdge": edge.rawValue,
      "safeArea": ["left": safe.left, "top": safe.top, "right": safe.right, "bottom": safe.bottom],
      "occlusions": occlusions.map(regionPayload),
      "divisions": divisions.map(regionPayload),
    ]
    #if DEBUG
    print("[fah] duo snapshot: \(payload)")
    #endif
    return payload
  }

  @available(iOS 27.1, *)
  private func regionPayload(_ region: UIView.ReservedRegion) -> [String: Any] {
    [
      "left": region.frame.minX,
      "top": region.frame.minY,
      "width": region.frame.width,
      "height": region.frame.height,
      "marginTop": region.margins.top,
      "marginRight": region.margins.right,
      "marginBottom": region.margins.bottom,
      "marginLeft": region.margins.left,
      "active": region.isActive,
    ]
  }
}

private var faDuoLayoutChannel: FaDuoLayoutChannel?

@MainActor
func registerDuoLayoutChannel(messenger: FlutterBinaryMessenger) {
  faDuoLayoutChannel = FaDuoLayoutChannel(messenger: messenger)
}

